simulated function EnsureVersusPlayerAnimationSet()
{
    // These two shipped meshes were made as playable variants and their
    // source explicitly names skHarryAnims as the shared player set. The
    // original import command accidentally assigns that set to skHarryMesh
    // again, leaving the player variants without Jump/Fall/Land. Link the
    // intended set per pawn; Tick also covers a Mesh value replicated after
    // PostNetBeginPlay on remote clients.
    if ((Mesh == SkeletalMesh'HPModels.skronPlayerMesh'
            || Mesh == SkeletalMesh'HPModels.skhermionePlayerMesh')
        && SkelAnim != Animation'HPModels.skHarryAnims')
    {
        LinkSkelAnim(Animation'HPModels.skHarryAnims');
    }
}

replacements.new:
simulated function EnsureVersusPlayerAnimationSet()
{
    // Profiles keep one gameplay pawn and one accepted movement pipeline.
    // Compatible cosmetic meshes are linked to the complete Harry player
    // animation set instead of inheriting partial NPC state animations.
    if (class'HPVersusCharacterProfiles'.static.ShouldLinkHarryAnimations(Mesh)
        && SkelAnim != Animation'HPModels.skHarryAnims')
    {
        LinkSkelAnim(Animation'HPModels.skHarryAnims');
    }
}

